{
  "status": "SUPPORTED",
  "task_summary": "Fasten assembly on workbench using compatible components and tool, then place tool on bench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "assembly_target",
        "entity_kind": "OBJECT",
        "function": "The object to be secured by fasteners.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["workpiece", "fixture"],
        "required_properties": ["surface_for_attachment"]
      },
      {
        "id": "fastener",
        "entity_kind": "OBJECT",
        "function": "Hardware used to secure the assembly.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["screw", "bolt", "nut"],
        "required_properties": ["threaded", "hole_matching"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "Implement used to apply the fastener.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["screwdriver", "wrench"],
        "required_properties": ["gripping_mechanism"]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "Surface where the assembly and tool are located.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "bench"],
        "required_properties": ["flat_surface"]
      }
    ],
    "functional_relations": [
      {
        "id": "relation_1",
        "relation": "is_compatible_with",
        "participant_roles": ["fastener", "assembly_target"]
      ,
        "required": true
      },
      {
        "id": "relation_2",
        "relation": "applies_to",
        "participant_roles": ["fastening_tool", "assembly_target"]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "op_1",
        "operation": "fasten",
        "participant_roles": ["fastening_tool", "fastener", "assembly_target"],
        "operation_count": 1
      },
      {
        "id": "op_2",
        "operation": "place_tool",
        "participant_roles": ["fastening_tool", "workbench"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "assembly_target": [
        {
          "label": "Yellow/Grey Assembly on Tray",
          "visual_description": "Rectangular assembly on black tray on workbench."
        }
      ],
      "fastener": [
        {
          "label": "Small items on tray",
          "visual_description": "Small grey/yellow pieces on the tray with the assembly."
        }
      ],
      "fastening_tool": [
        {
          "label": "Robot Gripper",
          "visual_description": "White robotic arm with yellow blocky end effector visible in third view."
        }
      ],
      "workbench": [
        {
          "label": "Wooden Table",
          "visual_description": "Brown wooden table with drawers."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "region_1",
        "label": "Left Drawer",
        "visual_description": "Blue drawer under the left side of the table.",
        "reason": "Closed storage structure, may contain spare fasteners or tools."
      },
      {
        "id": "region_2",
        "label": "Right Drawer",
        "visual_description": "Blue drawer under the right side of the table.",
        "reason": "Closed storage structure, may contain spare fasteners or tools."
      },
      {
        "id": "region_3",
        "label": "Tall Cabinet",
        "visual_description": "Blue cabinet against the wall behind the table.",
        "reason": "Closed storage structure, may contain tools or components."
      }
    ],
    "inspection_order": ["region_1", "region_2", "region_3"]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
  }
